#define main legacy_main
#include "../vol2col-cuda/main.cu"
#undef main
#include <vector>
#include <tuple>
#include <fstream>
#include <iostream>
#include <iomanip>
struct Case{int sd,k,cs;std::vector<float>x,cr,vr;float*a,*c;};
#define PARAMS 3,5,7,c.k,c.k,c.k,1,1,1,c.sd,c.sd,c.sd,c.sd,c.sd,c.sd,3,5,7
int main(){const int blocks=get_blocks(210);std::vector<Case>cases;std::vector<float>prefix;for(int sd:{2,1})for(int k:{1,3,5,7,9}){Case c;c.sd=sd;c.k=k;c.cs=(2*k*k*k+1)*192;c.x.resize(630);for(int i=0;i<630;i++)c.x[i]=float((i*17+3*k+sd)%101-50)/16;c.cr.assign(c.cs,0);c.vr=c.x;vol2col_reference<float>(c.x.data(),2,PARAMS,c.cr.data());col2vol_reference<float,float>(c.cr.data(),2,PARAMS,c.vr.data());cudaMalloc(&c.a,630*4);cudaMalloc(&c.c,c.cs*4);prefix.insert(prefix.end(),c.x.begin(),c.x.end());for(int q:{2,PARAMS,3})prefix.push_back(q);cases.push_back(c);}
auto run=[&](Case&c,std::vector<float>&out){cudaMemcpy(c.a,c.x.data(),630*4,cudaMemcpyHostToDevice);cudaMemset(c.c,0,c.cs*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<3;rep++)vol2col_kernel<float><<<blocks,512>>>(210,c.a,PARAMS,c.c);cudaDeviceSynchronize();double tf=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;std::vector<float>hc(c.cs),hv(630);cudaMemcpy(hc.data(),c.c,c.cs*4,cudaMemcpyDeviceToHost);cudaDeviceSynchronize();start=std::chrono::steady_clock::now();for(int rep=0;rep<3;rep++)col2vol_kernel<float,float><<<blocks,512>>>(210,c.c,PARAMS,c.a);cudaDeviceSynchronize();double tb=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;cudaMemcpy(hv.data(),c.a,630*4,cudaMemcpyDeviceToHost);bool ok=hc==c.cr&&hv==c.vr&&cudaGetLastError()==cudaSuccess;out.insert(out.end(),hc.begin(),hc.end());out.insert(out.end(),hv.begin(),hv.end());return std::make_tuple(tf,tb,ok);};std::vector<float>tmp;for(auto&c:cases)run(c,tmp);for(int trial=1;trial<=5;trial++){auto out=prefix;double elapsed=0;bool ok=true;std::cout<<"STUDY_COMPONENT_SECONDS ";for(auto&c:cases){auto[tf,tb,pass]=run(c,out);elapsed+=tf+tb;ok&=pass;std::cout<<std::setprecision(17)<<tf<<","<<tb<<",";}std::cout<<std::endl;std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();std::cout<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":0,\"timing_region\":\"sum20_three_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"float32\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}"<<std::endl;if(!ok)return 2;}}
